KG42.register("nodes-eea053defbec6fd3b7a5376d",{"id":"COMP-58e2723fe0b22957","code":"CLR029","label":"Service-quantity allocation using equal quotas and self-selection within limits","definition":"Initialize q_{i,t}=0 and Q_t=D_t^{AS} in each time period; for I^{**}={i∈I^*:q_{i,t}\u003cb_{i,t}^{AS}}, equally divide the remaining quota and update Q_t according to the original formula. After entering the final step, those with q_{i,t}≥b_{i,t}^{AS} take the declared quantity; otherwise, the customer selects the final procurement quantity within [0,q_{i,t}].","layer":"L5","template_code":"SRP","concept_id":"clearing.local","concept_ids":["clearing.local"],"identity_dimensions":{"identity_fields":["Object: customers with service demand and submitted quantity declarations","Core operation: equally allocate quotas, reallocate excess quotas, and determine final quantities according to conditions","Output: final service procurement quantity q_{i,t} for each customer"]},"exclusions":["The fairness intent is reflected in equal division; the declared quantity b_{i,t}^{AS} and demand D_t^{AS} are both in kW","The original update formulas are q_{i,t}←q_{i,t}+Q_t/|I^{**}| and Q_t←Σ_{i∈I^*}max(q_{i,t}−b_{i,t}^{AS},0)","If Q_t≠0 and I^{**} is non-empty, return to Step I; otherwise proceed to Step III; do not add intermediate truncation operations","I^{**} is the set currently requiring additional quota; the final quantity may be reduced by the customer"],"members":[{"id":"25-p2p_ancillary_bidding::v141-c-R014::V::clearing.local","rule_id":"v141-c-R014","market_meaning":"The utility, acting as coordinator of the community's ancillary-service procurement, determines which bids are accepted and the quantities procured. Scope: The utility's coordination of ancillary-service procurement from customers in the P2P energy trading community during the ancillary-service Agreement Period. Condition: After collecting customers' ancillary-service bids. Procurement quotas should initially distribute the requested service equally among submitting customers; quotas exceeding customers' bids are redistributed to customers needing additional quotas. Scope: Ancillary-service quota allocation among submitting customers in the P2P energy trading community, separately for each target time slot. Condition: After collecting ancillary-service bids, during quota distribution. Set the customer's final procurement quota equal to its submitted ancillary-service bid. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is at least its submitted ancillary-service bid. The customer chooses its final procurement quota between zero and its distributed quota, inclusive. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is below its submitted ancillary-service bid.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Ancillary-service quota allocation among submitting customers in the P2P energy trading community, separately for each target time slot. | Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. | The utility's coordination of ancillary-service procurement from customers in the P2P energy trading community during the ancillary-service Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E11-as-step3-fairness","v141-b-g02-E12-fig3-quota-algorithm"]},"constraint_refs":["25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C001","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C002","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C003","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C004","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C005","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C006","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C007","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C008","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C009","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C010"],"decision_anchor":"clearing.local","source_rule_sha256":"12bf5d09d9e158ac17ee525b2ca0faa70662119a8c18af6e50c91abdc53dec5f","paper":"25-p2p_ancillary_bidding","rule_ref":"25-p2p_ancillary_bidding::v141-c-R014","node_id":"clearing.local","function":"clearing.local","unit_id":"25-p2p_ancillary_bidding::v141-a-M03-ancillary-service::clearing.local","mechanism_id":"v141-a-M03-ancillary-service","anchor":true},{"id":"25-p2p_ancillary_bidding::v141-c-R016::V::clearing.local","rule_id":"v141-c-R016","market_meaning":"The allocated service quantity is used to calculate the customer's reward from the utility: Equation (23) multiplies the procured quantity by the ancillary-service price. Scope: Forward ancillary-service procurement among customers in the P2P community, for each target-period time slot. Condition: A Type-1 ancillary-service quantity is procured from a customer through the community procurement-allocation procedure. Prices specified in the affected P2P agreements enter the monetary adjustments. Compensation uses each agreement's price minus the feed-in tariff, multiplied by its reduced demand component and time-slot duration; the electricity payment avoided for that component uses the agreement's full price. Scope: Monetary adjustments to existing P2P energy trading agreements for Type-1 ancillary-service provision. Condition: The customer's baseline net load is positive, and Type-1 service reduces demand originally supplied through P2P agreements. The additional generated electricity is purchased by the utility at the feed-in tariff rate. Scope: Table 1 arrangements balancing electricity changes caused by ancillary-service provision. Condition: More electricity is generated in the ancillary-service adjustment. The additional consumed electricity is supplied by the utility at its retail price. Scope: Table 1 arrangements balancing electricity changes caused by ancillary-service provision. Condition: More electricity is consumed in the ancillary-service adjustment. An extra payment is owed to compensate the relevant customers for their revenue loss. Scope: Table 1 compensation arrangements for ancillary-service changes involving more electricity generated or consumed. Condition: The ancillary-service adjustment violates a P2P energy trading agreement. No penalty is payable for the P2G agreement violation in these adjustment cases. Scope: Table 1 penalty arrangements for ancillary-service changes involving more electricity generated or consumed. Condition: The ancillary-service adjustment violates a P2G residual-balancing agreement. The customer owes no P2G breach penalty and no longer owes the electricity charge for the demand that has been reduced. Scope: Type-1 ancillary-service demand reduction originally supplied under P2G residual-balancing agreements. Condition: The customer's baseline net load is positive, and the reduced demand was originally supplied by the utility.","omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Forward ancillary-service procurement among customers in the P2P community, for each target-period time slot. | Monetary adjustments to existing P2P energy trading agreements for Type-1 ancillary-service provision. | Table 1 arrangements balancing electricity changes caused by ancillary-service provision. | Table 1 compensation arrangements for ancillary-service changes involving more electricity generated or consumed. | Table 1 penalty arrangements for ancillary-service changes involving more electricity generated or consumed. | Type-1 ancillary-service demand reduction originally supplied under P2G residual-balancing agreements.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E11-as-step3-fairness","v141-b-g02-E14-table1-adjustments","v141-b-g02-E15-eq23-as-reward","v141-b-g02-E20-eq30-p2g-reduction-benefit","v141-b-g02-E22-eq32-penalty-cost","v141-b-g02-E23-eq33-avoided-p2p-cost-benefit"]},"constraint_refs":["25-p2p_ancillary_bidding::v141-c-R016::v141-c-R016-C001"],"decision_anchor":"settlement.payment","source_rule_sha256":"4b31b13a6fdac6eb7e232a302621f2d976130f03cf0656c9c0d84d8242057ae4","paper":"25-p2p_ancillary_bidding","rule_ref":"25-p2p_ancillary_bidding::v141-c-R016","node_id":"clearing.local","function":"clearing.local","unit_id":"25-p2p_ancillary_bidding::v141-a-M03-ancillary-service::clearing.local","mechanism_id":"v141-a-M03-ancillary-service","anchor":false}],"paper_ids":["25-p2p_ancillary_bidding"],"evidence":[{"evidence_id":"v141-b-g02-E09-as-step1-publication","location":{"location_id":"src-212077b9a1-p06-c1r2__v141-a-M03-bidding","page":6,"printed_page":null,"section":null,"anchor_text":"of the net load of a customer as a whole, rather than the change of power output/consumption of spec","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"As the first step, based on the assessment of the future operational status of power systems, the power utility will broadcast the total demand and prices of ancillary services to all the customers in the P2P energy trading community: \\(D^{AS}=\\{D_t^{AS}\\,|\\,t\\in T\\}\\), (15) \\(p^{AS}=\\{p_t^{AS}\\,|\\,t\\in T\\}\\), (16) where \\(D^{AS}\\) is the set of the magnitude (kW) of the ancillary services required for the time slots within the Target Time Period T, and \\(p^{AS}\\) is the set of prices (£/kW/h) that the power utility is willing to pay for the ancillary services provided by the customers. The power utility will also specify the type of ancillary services needed (either 'Type-1 AS' or 'Type-2 AS'). Note that how the power utility decides \\(D^{AS}\\) and \\(p^{AS}\\) involves comprehensive analysis of the power systems managed by the power utility, which is out of the scope of this paper.","paper":"25-p2p_ancillary_bidding","rule_id":"v141-c-R014","quote":"As the first step, based on the assessment of the future operational status of power systems, the power utility will broadcast the total demand and prices of ancillary services to all the customers in the P2P energy trading community: \\(D^{AS}=\\{D_t^{AS}\\,|\\,t\\in T\\}\\), (15) \\(p^{AS}=\\{p_t^{AS}\\,|\\,t\\in T\\}\\), (16) where \\(D^{AS}\\) is the set of the magnitude (kW) of the ancillary services required for the time slots within the Target Time Period T, and \\(p^{AS}\\) is the set of prices (£/kW/h) that the power utility is willing to pay for the ancillary services provided by the customers. The power utility will also specify the type of ancillary services needed (either 'Type-1 AS' or 'Type-2 AS'). Note that how the power utility decides \\(D^{AS}\\) and \\(p^{AS}\\) involves comprehensive analysis of the power systems managed by the power utility, which is out of the scope of this paper."},{"evidence_id":"v141-b-g02-E11-as-step3-fairness","location":{"location_id":"src-212077b9a1-p06-c2r1__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"Applied Energy 278 (2020) 115671 ng After collecting the bids from the customers in the P2P energy a","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined. To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need. With the above considerations, the process detailed in Fig. 3 is proposed for the power utility to decide the amount of services to be procured from the customers.","paper":"25-p2p_ancillary_bidding","rule_id":"v141-c-R014","quote":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined. To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need. With the above considerations, the process detailed in Fig. 3 is proposed for the power utility to decide the amount of services to be procured from the customers."},{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if","paper":"25-p2p_ancillary_bidding","rule_id":"v141-c-R014","quote":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"},{"evidence_id":"v141-b-g02-E11-as-step3-fairness","location":{"location_id":"src-212077b9a1-p06-c2r1__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"Applied Energy 278 (2020) 115671 ng After collecting the bids from the customers in the P2P energy a","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined. To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need. With the above considerations, the process detailed in Fig. 3 is proposed for the power utility to decide the amount of services to be procured from the customers.","paper":"25-p2p_ancillary_bidding","rule_id":"v141-c-R016","quote":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined. To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need. With the above considerations, the process detailed in Fig. 3 is proposed for the power utility to decide the amount of services to be procured from the customers."},{"evidence_id":"v141-b-g02-E15-eq23-as-reward","location":{"location_id":"src-212077b9a1-p07-c1r2__v141-a-M03-pricing","page":7,"printed_page":null,"section":null,"anchor_text":"Without loss of generality, it is assumed that the magnitude of Type-1 AS procured from a customer i","equation_id":"(23)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"Without loss of generality, it is assumed that the magnitude of Type-1 AS procured from a customer i for the time slot t is \\(q_{i,t}\\) (kW), as decided through the procedure shown in Fig. 3. Recall that the Type-1 AS refers to the demand reduction or generation increase of the customer i as a whole, which is measured with the baseline being the net load profile of the customer, \\(NL^*_{i,t}\\), calculated in Section 3.2. First of all, because of the provision of the ancillary service, the customer will receive reward from the power utility, as presented in Section 5.1.2. The associated benefit, \\(\\Delta B_{q_{i,t}}^{AS}\\), is expressed as \\(\\Delta B_{q_{i,t}}^{AS}=p_t^{AS}\\cdot q_{i,t}\\quad \\forall i\\in I^*, t\\in T.\\) (23)","paper":"25-p2p_ancillary_bidding","rule_id":"v141-c-R016","quote":"Without loss of generality, it is assumed that the magnitude of Type-1 AS procured from a customer i for the time slot t is \\(q_{i,t}\\) (kW), as decided through the procedure shown in Fig. 3. Recall that the Type-1 AS refers to the demand reduction or generation increase of the customer i as a whole, which is measured with the baseline being the net load profile of the customer, \\(NL^*_{i,t}\\), calculated in Section 3.2. First of all, because of the provision of the ancillary service, the customer will receive reward from the power utility, as presented in Section 5.1.2. The associated benefit, \\(\\Delta B_{q_{i,t}}^{AS}\\), is expressed as \\(\\Delta B_{q_{i,t}}^{AS}=p_t^{AS}\\cdot q_{i,t}\\quad \\forall i\\in I^*, t\\in T.\\) (23)"}],"candidate_only":true,"classification_subtypes":["equal_share_quota_allocation"],"projection_statuses":["clear"],"taxonomy":{"primary_family":"kind-L5-95e97c5fd0","secondary_families":[],"stage":"L5","ontological_kind":"equal_share_quota_allocation"},"semantic_definition":{},"source_units":[{"unit_id":"25-p2p_ancillary_bidding::v141-a-M03-ancillary-service::clearing.local","paper_id":"25-p2p_ancillary_bidding","mechanism_id":"v141-a-M03-ancillary-service","function":"clearing.local","source_occurrences":[{"id":"25-p2p_ancillary_bidding::v141-c-R014::V::clearing.local","rule_id":"v141-c-R014","market_meaning":"The utility, acting as coordinator of the community's ancillary-service procurement, determines which bids are accepted and the quantities procured. Scope: The utility's coordination of ancillary-service procurement from customers in the P2P energy trading community during the ancillary-service Agreement Period. Condition: After collecting customers' ancillary-service bids. Procurement quotas should initially distribute the requested service equally among submitting customers; quotas exceeding customers' bids are redistributed to customers needing additional quotas. Scope: Ancillary-service quota allocation among submitting customers in the P2P energy trading community, separately for each target time slot. Condition: After collecting ancillary-service bids, during quota distribution. Set the customer's final procurement quota equal to its submitted ancillary-service bid. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is at least its submitted ancillary-service bid. The customer chooses its final procurement quota between zero and its distributed quota, inclusive. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is below its submitted ancillary-service bid.","omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Ancillary-service quota allocation among submitting customers in the P2P energy trading community, separately for each target time slot. | Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. | The utility's coordination of ancillary-service procurement from customers in the P2P energy trading community during the ancillary-service Agreement Period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E11-as-step3-fairness","v141-b-g02-E12-fig3-quota-algorithm"]},"constraint_refs":["25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C001","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C002","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C003","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C004","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C005","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C006","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C007","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C008","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C009","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C010"],"decision_anchor":"clearing.local","source_rule_sha256":"12bf5d09d9e158ac17ee525b2ca0faa70662119a8c18af6e50c91abdc53dec5f"},{"id":"25-p2p_ancillary_bidding::v141-c-R016::V::clearing.local","rule_id":"v141-c-R016","market_meaning":"The allocated service quantity is used to calculate the customer's reward from the utility: Equation (23) multiplies the procured quantity by the ancillary-service price. Scope: Forward ancillary-service procurement among customers in the P2P community, for each target-period time slot. Condition: A Type-1 ancillary-service quantity is procured from a customer through the community procurement-allocation procedure. Prices specified in the affected P2P agreements enter the monetary adjustments. Compensation uses each agreement's price minus the feed-in tariff, multiplied by its reduced demand component and time-slot duration; the electricity payment avoided for that component uses the agreement's full price. Scope: Monetary adjustments to existing P2P energy trading agreements for Type-1 ancillary-service provision. Condition: The customer's baseline net load is positive, and Type-1 service reduces demand originally supplied through P2P agreements. The additional generated electricity is purchased by the utility at the feed-in tariff rate. Scope: Table 1 arrangements balancing electricity changes caused by ancillary-service provision. Condition: More electricity is generated in the ancillary-service adjustment. The additional consumed electricity is supplied by the utility at its retail price. Scope: Table 1 arrangements balancing electricity changes caused by ancillary-service provision. Condition: More electricity is consumed in the ancillary-service adjustment. An extra payment is owed to compensate the relevant customers for their revenue loss. Scope: Table 1 compensation arrangements for ancillary-service changes involving more electricity generated or consumed. Condition: The ancillary-service adjustment violates a P2P energy trading agreement. No penalty is payable for the P2G agreement violation in these adjustment cases. Scope: Table 1 penalty arrangements for ancillary-service changes involving more electricity generated or consumed. Condition: The ancillary-service adjustment violates a P2G residual-balancing agreement. The customer owes no P2G breach penalty and no longer owes the electricity charge for the demand that has been reduced. Scope: Type-1 ancillary-service demand reduction originally supplied under P2G residual-balancing agreements. Condition: The customer's baseline net load is positive, and the reduced demand was originally supplied by the utility.","omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Forward ancillary-service procurement among customers in the P2P community, for each target-period time slot. | Monetary adjustments to existing P2P energy trading agreements for Type-1 ancillary-service provision. | Table 1 arrangements balancing electricity changes caused by ancillary-service provision. | Table 1 compensation arrangements for ancillary-service changes involving more electricity generated or consumed. | Table 1 penalty arrangements for ancillary-service changes involving more electricity generated or consumed. | Type-1 ancillary-service demand reduction originally supplied under P2G residual-balancing agreements.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E11-as-step3-fairness","v141-b-g02-E14-table1-adjustments","v141-b-g02-E15-eq23-as-reward","v141-b-g02-E20-eq30-p2g-reduction-benefit","v141-b-g02-E22-eq32-penalty-cost","v141-b-g02-E23-eq33-avoided-p2p-cost-benefit"]},"constraint_refs":["25-p2p_ancillary_bidding::v141-c-R016::v141-c-R016-C001"],"decision_anchor":"settlement.payment","source_rule_sha256":"4b31b13a6fdac6eb7e232a302621f2d976130f03cf0656c9c0d84d8242057ae4"}],"constraints":[{"constraint_id":"v141-c-R014-C001","kind":"procedural","role":"core","statement":"The utility, acting as coordinator of the community's ancillary-service procurement, determines which bids are accepted and the quantities procured. Scope: The utility's coordination of ancillary-service procurement from customers in the P2P energy trading community during the ancillary-service Agreement Period. Condition: After collecting customers' ancillary-service bids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","clearing.local"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E11-as-step3-fairness"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C001","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E09-as-step1-publication","location":{"location_id":"src-212077b9a1-p06-c1r2__v141-a-M03-bidding","page":6,"printed_page":null,"section":null,"anchor_text":"of the net load of a customer as a whole, rather than the change of power output/consumption of spec","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"As the first step, based on the assessment of the future operational status of power systems, the power utility will broadcast the total demand and prices of ancillary services to all the customers in the P2P energy trading community: \\(D^{AS}=\\{D_t^{AS}\\,|\\,t\\in T\\}\\), (15) \\(p^{AS}=\\{p_t^{AS}\\,|\\,t\\in T\\}\\), (16) where \\(D^{AS}\\) is the set of the magnitude (kW) of the ancillary services required for the time slots within the Target Time Period T, and \\(p^{AS}\\) is the set of prices (£/kW/h) that the power utility is willing to pay for the ancillary services provided by the customers. The power utility will also specify the type of ancillary services needed (either 'Type-1 AS' or 'Type-2 AS'). Note that how the power utility decides \\(D^{AS}\\) and \\(p^{AS}\\) involves comprehensive analysis of the power systems managed by the power utility, which is out of the scope of this paper."},{"evidence_id":"v141-b-g02-E11-as-step3-fairness","location":{"location_id":"src-212077b9a1-p06-c2r1__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"Applied Energy 278 (2020) 115671 ng After collecting the bids from the customers in the P2P energy a","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined. To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need. With the above considerations, the process detailed in Fig. 3 is proposed for the power utility to decide the amount of services to be procured from the customers."}]},{"constraint_id":"v141-c-R014-C002","kind":"procedural","role":"core","statement":"Procurement quotas should initially distribute the requested service equally among submitting customers; quotas exceeding customers' bids are redistributed to customers needing additional quotas. Scope: Ancillary-service quota allocation among submitting customers in the P2P energy trading community, separately for each target time slot. Condition: After collecting ancillary-service bids, during quota distribution.","expression":"q_{i,t}\\leftarrow 0\\quad \\forall i\\in I^*;\\qquad Q_t\\leftarrow D_t^{AS};\\qquad \\text{repeat } I^{**}={i\\in I^*\\mid q_{i,t}-b_{i,t}^{AS}\u003c0};\\quad q_{i,t}\\leftarrow q_{i,t}+\\frac{Q_t}{|I^{**}|}\\ \\forall i\\in I^{**};\\quad Q_t\\leftarrow\\sum_{i\\in I^*}\\max(q_{i,t}-b_{i,t}^{AS},0)\\ \\text{until }Q_t=0\\text{ or }I^{**}=\\varnothing.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q","v141-c-R014-v-Q","v141-c-R014-v-Istarstar"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-D","v141-c-R014-p-Istar","v141-c-R014-p-T"],"evidence_ids":["v141-b-g02-E11-as-step3-fairness","v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E09-as-step1-publication"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C002","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E11-as-step3-fairness","location":{"location_id":"src-212077b9a1-p06-c2r1__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"Applied Energy 278 (2020) 115671 ng After collecting the bids from the customers in the P2P energy a","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined. To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need. With the above considerations, the process detailed in Fig. 3 is proposed for the power utility to decide the amount of services to be procured from the customers."},{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"},{"evidence_id":"v141-b-g02-E09-as-step1-publication","location":{"location_id":"src-212077b9a1-p06-c1r2__v141-a-M03-bidding","page":6,"printed_page":null,"section":null,"anchor_text":"of the net load of a customer as a whole, rather than the change of power output/consumption of spec","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"As the first step, based on the assessment of the future operational status of power systems, the power utility will broadcast the total demand and prices of ancillary services to all the customers in the P2P energy trading community: \\(D^{AS}=\\{D_t^{AS}\\,|\\,t\\in T\\}\\), (15) \\(p^{AS}=\\{p_t^{AS}\\,|\\,t\\in T\\}\\), (16) where \\(D^{AS}\\) is the set of the magnitude (kW) of the ancillary services required for the time slots within the Target Time Period T, and \\(p^{AS}\\) is the set of prices (£/kW/h) that the power utility is willing to pay for the ancillary services provided by the customers. The power utility will also specify the type of ancillary services needed (either 'Type-1 AS' or 'Type-2 AS'). Note that how the power utility decides \\(D^{AS}\\) and \\(p^{AS}\\) involves comprehensive analysis of the power systems managed by the power utility, which is out of the scope of this paper."}]},{"constraint_id":"v141-c-R014-C003","kind":"procedural","role":"core","statement":"Set the customer's final procurement quota equal to its submitted ancillary-service bid. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is at least its submitted ancillary-service bid.","expression":"q_{i,t}=b_{i,t}^{AS}\\quad\\text{if }q_{i,t}\\ge b_{i,t}^{AS},\\ \\forall i\\in I^*,\\ t\\in T.","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-Istar","v141-c-R014-p-T"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C003","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"}]},{"constraint_id":"v141-c-R014-C004","kind":"procedural","role":"core","statement":"The customer chooses its final procurement quota between zero and its distributed quota, inclusive. Scope: Step III of ancillary-service procurement allocation, for each submitting customer and target time slot. Condition: The customer's distributed quota is below its submitted ancillary-service bid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-Istar","v141-c-R014-p-T"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C004","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"}]},{"constraint_id":"v141-c-R014-C005","kind":"mathematical","role":"supporting","statement":"For each target time slot, initialize the ancillary-service procurement quota of every submitting customer to zero.","expression":"q_{i,t}=0\\quad \\forall i\\in I^*\\quad\\text{(for each }t\\in T\\text{)}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q"],"parameter_refs":["v141-c-R014-p-Istar","v141-c-R014-p-T"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C005","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"}]},{"constraint_id":"v141-c-R014-C006","kind":"mathematical","role":"supporting","statement":"Initialize the sum of surplus quotas for the target time slot to the total ancillary-service demand.","expression":"Q_t=D_t^{AS}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-Q"],"parameter_refs":["v141-c-R014-p-D"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm","v141-b-g02-E09-as-step1-publication"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C006","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"},{"evidence_id":"v141-b-g02-E09-as-step1-publication","location":{"location_id":"src-212077b9a1-p06-c1r2__v141-a-M03-bidding","page":6,"printed_page":null,"section":null,"anchor_text":"of the net load of a customer as a whole, rather than the change of power output/consumption of spec","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"As the first step, based on the assessment of the future operational status of power systems, the power utility will broadcast the total demand and prices of ancillary services to all the customers in the P2P energy trading community: \\(D^{AS}=\\{D_t^{AS}\\,|\\,t\\in T\\}\\), (15) \\(p^{AS}=\\{p_t^{AS}\\,|\\,t\\in T\\}\\), (16) where \\(D^{AS}\\) is the set of the magnitude (kW) of the ancillary services required for the time slots within the Target Time Period T, and \\(p^{AS}\\) is the set of prices (£/kW/h) that the power utility is willing to pay for the ancillary services provided by the customers. The power utility will also specify the type of ancillary services needed (either 'Type-1 AS' or 'Type-2 AS'). Note that how the power utility decides \\(D^{AS}\\) and \\(p^{AS}\\) involves comprehensive analysis of the power systems managed by the power utility, which is out of the scope of this paper."}]},{"constraint_id":"v141-c-R014-C007","kind":"mathematical","role":"supporting","statement":"Generate the set of submitting customers whose current quotas are lower than their submitted bids.","expression":"I^{**}={i\\in I^*\\mid q_{i,t}-b_{i,t}^{AS}\u003c0}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q","v141-c-R014-v-Istarstar"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-Istar"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C007","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"}]},{"constraint_id":"v141-c-R014-C008","kind":"mathematical","role":"supporting","statement":"Distribute the total surplus quota equally among the customers who need more quota.","expression":"q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q","v141-c-R014-v-Q","v141-c-R014-v-Istarstar"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C008","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"}]},{"constraint_id":"v141-c-R014-C009","kind":"mathematical","role":"supporting","statement":"Calculate the total surplus quota as the sum over submitting customers of the positive excess of current quota over submitted bid.","expression":"Q_t=\\sum_{i\\in I^*}\\max(q_{i,t}-b_{i,t}^{AS},0)","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-q","v141-c-R014-v-Q"],"parameter_refs":["v141-c-R014-p-b","v141-c-R014-p-Istar"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C009","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"}]},{"constraint_id":"v141-c-R014-C010","kind":"procedural","role":"supporting","statement":"If the surplus quota is nonzero and the set of quota-needing customers is nonempty, return to Step I; otherwise continue to Step III.","expression":"\\text{if }Q_t\\ne0\\text{ and }I^{**}\\ne\\varnothing\\text{ then repeat Step I; otherwise continue to Step III}","formalization_origin":"source","template_id":null,"members":["clearing.local"],"variable_refs":["v141-c-R014-v-Q","v141-c-R014-v-Istarstar"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"ref":"25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C010","source_rule_id":"v141-c-R014","evidence":[{"evidence_id":"v141-b-g02-E12-fig3-quota-algorithm","location":{"location_id":"src-212077b9a1-p06-c2r4__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"7) he at he d. he e­ Fig. 3. Distribution of the ancillary service procurement among customers. 6","equation_id":"(18)-(22)","figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Distribution of the ancillary service procurement among customers (for each time slot t in the Target Time Period T)\nInitialization:\nInitialize the amount of ancillary service to be procured from each customer (i.e. the 'quota'), \\(q_{i,t}\\), by \\(q_{i,t}=0\\quad \\forall i\\in I^*\\), (18) and initialize the sum of the surplus quotas of all customers, \\(Q_t=D_t^{AS}\\). (19)\nStep I:\nFirst generate the set of customers whose quotas are lower than their bids by \\(I^{**}=\\{i\\in I^*\\,|\\,q_{i,t}-b_{i,t}^{AS}\u003c0\\}\\). (20)\nThen distribute the total surplus quota averagely on the customers who need more quotas by \\(q_{i,t}=q_{i,t}+\\frac{Q_t}{|I^{**}|}\\quad \\forall i\\in I^{**}\\). (21)\nStep II:\nCalculate the total surplus quota by \\(Q_t=\\sum_{i\\in I^*}(\\max(q_{i,t}-b_{i,t}^{AS},0))\\). (22)\nIf \\(Q_t\\ne 0\\) and \\(I^{**}\\ne \\varnothing\\), go back to Step I. Otherwise, continue to Step III.\nStep III:\nDecide the amount of ancillary service to be procured from each customer according to the following logic (presented as pseudo-codes):\n1. if \\(q_{i,t}\\ge b_{i,t}^{AS}\\)\n2. \\(q_{i,t}=b_{i,t}^{AS}\\)\n3. else\n4. the customer i chooses a value from \\([0,q_{i,t}]\\) as the final \\(q_{i,t}\\)\n5. end if"}]},{"constraint_id":"v141-c-R016-C001","kind":"mathematical","role":"core","statement":"The allocated service quantity is used to calculate the customer's reward from the utility: Equation (23) multiplies the procured quantity by the ancillary-service price. Scope: Forward ancillary-service procurement among customers in the P2P community, for each target-period time slot. Condition: A Type-1 ancillary-service quantity is procured from a customer through the community procurement-allocation procedure.","expression":"\\Delta B^{AS}_{q_{i,t}} = p_t^{AS}\\cdot q_{i,t}\\quad \\forall i\\in I^*, t\\in T.","formalization_origin":"source","template_id":null,"members":["clearing.local","settlement.payment"],"variable_refs":["v141-c-R016-x-q-it"],"parameter_refs":["v141-c-R016-theta-pAS-t"],"evidence_ids":["v141-b-g02-E11-as-step3-fairness","v141-b-g02-E15-eq23-as-reward"],"ref":"25-p2p_ancillary_bidding::v141-c-R016::v141-c-R016-C001","source_rule_id":"v141-c-R016","evidence":[{"evidence_id":"v141-b-g02-E11-as-step3-fairness","location":{"location_id":"src-212077b9a1-p06-c2r1__v141-a-M03-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"Applied Energy 278 (2020) 115671 ng After collecting the bids from the customers in the P2P energy a","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"After collecting the bids from the customers in the P2P energy trading community (a time window can be defined in the Agreement Period for this purpose), the power utility needs to decide which of and to what extent the bids are to be accepted/declined. To achieve the fairness, the power utility in principle should distribute the amount of services to be procured averagely on the customers who have submitted the bids. However, the amount of services to be procured from each customer (called as the 'quota') calculated in this way may be higher than some customers' bids, and thus the surplus quotas can be given to other customers in need. With the above considerations, the process detailed in Fig. 3 is proposed for the power utility to decide the amount of services to be procured from the customers."},{"evidence_id":"v141-b-g02-E15-eq23-as-reward","location":{"location_id":"src-212077b9a1-p07-c1r2__v141-a-M03-pricing","page":7,"printed_page":null,"section":null,"anchor_text":"Without loss of generality, it is assumed that the magnitude of Type-1 AS procured from a customer i","equation_id":"(23)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"Without loss of generality, it is assumed that the magnitude of Type-1 AS procured from a customer i for the time slot t is \\(q_{i,t}\\) (kW), as decided through the procedure shown in Fig. 3. Recall that the Type-1 AS refers to the demand reduction or generation increase of the customer i as a whole, which is measured with the baseline being the net load profile of the customer, \\(NL^*_{i,t}\\), calculated in Section 3.2. First of all, because of the provision of the ancillary service, the customer will receive reward from the power utility, as presented in Section 5.1.2. The associated benefit, \\(\\Delta B_{q_{i,t}}^{AS}\\), is expressed as \\(\\Delta B_{q_{i,t}}^{AS}=p_t^{AS}\\cdot q_{i,t}\\quad \\forall i\\in I^*, t\\in T.\\) (23)"}]}],"variables":[{"variable_id":"v141-c-R014-v-q","symbol":"q_{i,t}","meaning":"Amount of ancillary service to be procured from customer i for target time slot t (the quota), initialized and updated by the Fig. 3 quota-allocation algorithm; after Step III it is the final procurement quota.","kind":"operational","domain":"kW; quota amount for customer i in submitting set I* and target time slot t, initialized at 0 and updated by nonnegative surplus allocation in the clearing procedure","unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"source_rule_id":"v141-c-R014","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R014::x::v141-c-R014-v-q"},{"variable_id":"v141-c-R014-v-Q","symbol":"Q_t","meaning":"Sum of surplus quotas of all customers for target time slot t in the current iteration of the quota-allocation algorithm.","kind":"operational","domain":"kW; initialized to D_t^{AS} and recomputed by Eq. (22) in the clearing procedure","unit":"kW","indices":["t"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"source_rule_id":"v141-c-R014","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R014::x::v141-c-R014-v-Q"},{"variable_id":"v141-c-R014-v-Istarstar","symbol":"I^{**}","meaning":"Set of submitting customers whose current quota is lower than their submitted bid and therefore need additional quota.","kind":"operational","domain":"Subset of I* satisfying q_{i,t}-b_{i,t}^{AS}\u003c0 at the current iteration for target time slot t.","unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-E12-fig3-quota-algorithm"],"source_rule_id":"v141-c-R014","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R014::x::v141-c-R014-v-Istarstar"},{"variable_id":"v141-c-R016-x-q-it","symbol":"q_{i,t}","meaning":"Magnitude of Type-1 ancillary service procured from customer i in time slot t, as decided by the quota procedure and used in the ancillary-service reward payment.","kind":"operational","domain":"nonnegative real (kW magnitude; Fig. 3 initializes the quota at 0 and allocates the service quantity)","unit":"kW","indices":["i∈I*","t∈T"],"evidence_ids":["v141-b-g02-E15-eq23-as-reward","v141-b-g02-E12-fig3-quota-algorithm"],"source_rule_id":"v141-c-R016","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R016::x::v141-c-R016-x-q-it"}],"parameters":[{"parameter_id":"v141-c-R014-p-b","symbol":"b_{i,t}^{AS}","meaning":"Magnitude of the ancillary-service bid submitted by customer i for target time slot t; used as an input to the quota-allocation procedure.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g02-E10-as-step2-bid-form-eq17","v141-b-g02-E12-fig3-quota-algorithm"],"source_rule_id":"v141-c-R014","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R014::theta::v141-c-R014-p-b"},{"parameter_id":"v141-c-R014-p-D","symbol":"D_t^{AS}","meaning":"Total magnitude of ancillary service required for target time slot t, published by the power utility; used to initialize the total surplus quota Q_t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kW","indices":["t"],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E12-fig3-quota-algorithm"],"source_rule_id":"v141-c-R014","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R014::theta::v141-c-R014-p-D"},{"parameter_id":"v141-c-R014-p-Istar","symbol":"I^*","meaning":"Set of customers who submit ancillary-service bids.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E10-as-step2-bid-form-eq17","v141-b-g02-E12-fig3-quota-algorithm"],"source_rule_id":"v141-c-R014","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R014::theta::v141-c-R014-p-Istar"},{"parameter_id":"v141-c-R014-p-T","symbol":"T","meaning":"Set of time slots within the Target Time Period T for which the ancillary-service procurement allocation is performed.","value":{"kind":"symbolic","number_value":null,"text_value":"Target Time Period T"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E09-as-step1-publication","v141-b-g02-E12-fig3-quota-algorithm"],"source_rule_id":"v141-c-R014","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R014::theta::v141-c-R014-p-T"},{"parameter_id":"v141-c-R016-theta-pAS-t","symbol":"p_t^{AS}","meaning":"Ancillary-service price published by the utility for time slot t, used in the Type-1 ancillary-service reward formula.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"£/kW/h","indices":["t∈T"],"evidence_ids":["v141-b-g02-E15-eq23-as-reward","v141-b-g02-E09-as-step1-publication"],"source_rule_id":"v141-c-R016","declaration_ref":"25-p2p_ancillary_bidding::v141-c-R016::theta::v141-c-R016-theta-pAS-t"}]}],"source_definitions":[{"unit_id":"25-p2p_ancillary_bidding::v141-a-M03-ancillary-service::clearing.local","stage":"L5","subtype":"equal_share_quota_allocation","projection_status":"clear","target_definition":"Initialize q_{i,t}=0 and Q_t=D_t^{AS} in each time period; for I^{**}={i∈I^*:q_{i,t}\u003cb_{i,t}^{AS}}, equally divide the remaining quota and update Q_t according to the original formula. After entering the final step, those with q_{i,t}≥b_{i,t}^{AS} take the declared quantity; otherwise, the customer selects the final procurement quantity within [0,q_{i,t}].","form_kind":"procedural","identity_fields":["Object: customers with service demand and submitted quantity declarations","Core operation: equally allocate quotas, reallocate excess quotas, and determine final quantities according to conditions","Output: final service procurement quantity q_{i,t} for each customer"],"variation_fields":["The fairness intent is reflected in equal division; the declared quantity b_{i,t}^{AS} and demand D_t^{AS} are both in kW","The original update formulas are q_{i,t}←q_{i,t}+Q_t/|I^{**}| and Q_t←Σ_{i∈I^*}max(q_{i,t}−b_{i,t}^{AS},0)","If Q_t≠0 and I^{**} is non-empty, return to Step I; otherwise proceed to Step III; do not add intermediate truncation operations","I^{**} is the set currently requiring additional quota; the final quantity may be reduced by the customer"],"constraint_refs":["25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C002","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C003","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C004","25-p2p_ancillary_bidding::v141-c-R014::v141-c-R014-C010","25-p2p_ancillary_bidding::v141-c-R016::v141-c-R016-C001"],"paper_id":"25-p2p_ancillary_bidding","mechanism_id":"v141-a-M03-ancillary-service","function":"clearing.local","template_code":"SRP"}],"source_variants":[],"functional":{"is_child":false,"subdivision_pending":false},"canonical_pointer":"/nodes/114"});
